-- Raw invocations enter curated history only when referenced. Index refs and
-- retained actor envelopes cover every previously completed export; new
-- referring records and index memberships invalidate independently.
ALTER TABLE history_sync_generation ADD COLUMN cause TEXT NOT NULL DEFAULT '';

DROP TRIGGER history_sync_actor_invocations_insert;
CREATE TRIGGER history_sync_actor_invocations_insert AFTER INSERT ON "actor_invocations" WHEN (EXISTS(SELECT 1 FROM history_index_refs WHERE project_id=new.project_id AND ref_kind='actor_invocation' AND ref_id=new.id) OR EXISTS(SELECT 1 FROM portable_envelopes WHERE project_id=new.project_id AND record_type='actor_invocation' AND record_id=new.id)) BEGIN UPDATE history_sync_generation SET token=lower(hex(randomblob(16))),cause='history_sync_actor_invocations_insert' WHERE id=1; END;
DROP TRIGGER history_sync_actor_invocations_update;
