CREATE TRIGGER history_sync_actor_invocations_delete AFTER DELETE ON "actor_invocations" WHEN (EXISTS(SELECT 1 FROM history_index_refs WHERE project_id=old.project_id AND ref_kind='actor_invocation' AND ref_id=old.id) OR EXISTS(SELECT 1 FROM portable_envelopes WHERE project_id=old.project_id AND record_type='actor_invocation' AND record_id=old.id)) BEGIN UPDATE history_sync_generation SET token=lower(hex(randomblob(16))),cause='history_sync_actor_invocations_delete' WHERE id=1; END;
